package main

import (
	"context"
	"crypto/tls"
	"log"
	"net/http"
	"net/http/httputil"
	"net/url"

	"github.com/coder/websocket"
	"github.com/elazarl/goproxy"
)

func main() {
	echoSrv, echoTr, err := startEchoBackend()
	if err != nil {
		log.Fatal(err)
	}
	defer echoSrv.Close()

	proxy := goproxy.NewProxyHttpServer()

	// MITM every CONNECT request, so that the WebSocket handshake over
	// HTTPS can be intercepted and proxied.
	proxy.OnRequest().HandleConnect(goproxy.AlwaysMitm)

	// The backend serves a certificate generated by httptest (valid only for
	// example.com), so the upstream connection uses the custom transport.
	proxy.OnRequest(goproxy.ReqHostIs("localhost:11000")).DoFunc(func(req *http.Request, ctx *goproxy.ProxyCtx) (*http.Request, *http.Response) {
		ctx.RoundTripper = &roundTripper{tr: echoTr}
		return req, nil
	})

	// Dump and log the WebSocket handshake request, then let GoProxy
	// establish the connection with the WebSocket server for the client
	proxy.OnRequest().DoFunc(func(req *http.Request, ctx *goproxy.ProxyCtx) (*http.Request, *http.Response) {
		dump, err := httputil.DumpRequest(req, false)
		if err != nil {
			log.Printf("WebSocket handshake dump error: %v", err)
		} else {
			log.Printf("WebSocket handshake request dump:\n%s", dump)
		}
		return req, nil
	})

	log.Printf("proxy listening on :10999")
	go func() {
		log.Fatal(http.ListenAndServe(":10999", proxy))
	}()

	ctx := context.Background()
	c, _, err := websocket.Dial(ctx, "wss://localhost:11000", &websocket.DialOptions{
		HTTPClient: &http.Client{
			Transport: &http.Transport{
				TLSClientConfig: &tls.Config{
					InsecureSkipVerify: true,
				},
				Proxy: http.ProxyURL(&url.URL{
					Scheme: "http",
					Host:   "localhost:10999",
				}),
			},
		},
	})
	if err != nil {
		log.Fatal("dial:", err)
	}
	defer func() {
		_ = c.Close(websocket.StatusNormalClosure, "")
	}()

	for _, msg := range []string{"Hello", "World"} {
		log.Printf("client send: %s", msg)
		if err := c.Write(ctx, websocket.MessageText, []byte(msg)); err != nil {
			log.Fatal("write:", err)
		}

		_, response, err := c.Read(ctx)
		if err != nil {
			log.Fatal("read:", err)
		}
		log.Printf("client received: %s", response)
	}
}

type roundTripper struct {
	tr http.RoundTripper
}

func (r *roundTripper) RoundTrip(req *http.Request, _ *goproxy.ProxyCtx) (*http.Response, error) {
	return r.tr.RoundTrip(req)
}
